NEW_FILES = {'tests/service/test_revise.py': '"""Change a level\'s settings and see the change in the next walk (0.248.0, the factory\'s roadmap 316).\n\nA change is a new revision, never an overwrite: the revision the change was made to must still be the saved one, an\nunchanged save is refused, and the answer says what the change rebuilds. The walk builds the CURRENT revision -- its\nbrief re-written and re-imported before the art leg -- and refuses when a change made the chosen layout stale.\nFAILS ON 0.247.0: no update_design.\n"""\nimport json\nimport sys\nfrom pathlib import Path\n\nimport pytest\n\nROOT = Path(__file__).resolve().parents[2]\nsys.path.insert(0, str(ROOT))\n\nfrom packages.service import design, layouts, operations, walking  # noqa: E402\nfrom packages.service.worker import EventSink, RequestError  # noqa: E402\n\n_NOOP = type("E", (), {"emit": lambda self, *a, **k: None})()\n\n\n@pytest.fixture\ndef level(tmp_path, monkeypatch):\n    from packages.tools import discovery\n    monkeypatch.setattr(discovery, "factory_root", lambda start=None: tmp_path)\n    got = operations.create_design({"template": "restaurant_row", "name": "Late Shift"}, _NOOP)\n    run_dir = tmp_path / "run"\n    run_dir.mkdir()\n    return got, run_dir\n\n\ndef _save(got, **kw):\n    return operations.update_design(dict({"path": got["path"]}, **kw), _NOOP)\n\n\ndef test_a_change_is_the_next_revision_and_says_what_it_rebuilds(level):\n    got, _ = level\n    out = _save(got, revision=1, choices={"time_of_day": "midnight"})\n    assert out["design"]["revision"] == 2 and out["rebuilds"] == ["lighting"]\n    assert json.loads(Path(out["path"]).read_text(encoding="utf-8"))["choices"]["time_of_day"] == "midnight"\n    assert out["brief"]["time_of_day"] == "midnight"\n    out = _save(got, revision=2, choices={"road_grammar": "block"})\n    assert out["rebuilds"] == ["layout"]\n    out = _save(got, revision=3, intent={"notes": "after closing"})\n    assert out["rebuilds"] == [] and out["design"]["revision"] == 4\n\n\ndef test_a_stale_revision_and_an_unchanged_save_are_refused(level):\n    got, _ = level\n    _save(got, revision=1, choices={"time_of_day": "morning"})\n    with pytest.raises(RequestError) as e:\n        _save(got, revision=1, choices={"time_of_day": "noon"})\n    assert e.value.code == "conflict"\n    with pytest.raises(RequestError) as e:\n        _save(got, revision=2, choices={"time_of_day": "morning"})\n    assert e.value.code == "nothing_changed"\n    with pytest.raises(RequestError) as e:\n        _save(got, revision=2, choices={"time_of_day": "dusk"})\n    assert e.value.code == "bad_choice"\n\n\ndef _workspace_with_layouts(got, run_dir, brief):\n    folder = Path(got["path"]).parent\n    ws = folder / "workspace"\n    (ws / ".level_factory" / "approvals").mkdir(parents=True)\n    (ws / "factory.project.json").write_text("{}", encoding="utf-8")\n    (ws / ".level_factory" / "approvals" / "late_shift_001.selected").write_text(\n        "late_shift_001.candidate.seed_9003", encoding="utf-8")\n    layouts._write_json(folder / "builds" / "revision_1.json", {"brief": brief, "candidates": []})\n    return ws\n\n\ndef _fake(calls):\n    def leg(argv, log, *, cancel_file, on_poll=None):\n        calls.append(argv)\n        if argv[2:3] == ["walk"]:\n            prev = Path(argv[1]) / ".level_factory" / "preview" / "late_shift_001_walk"\n            prev.mkdir(parents=True)\n            (prev / "project.godot").write_text("", encoding="utf-8")\n        return 0\n    return leg\n\n\ndef test_the_walk_builds_the_current_revision(level):\n    got, run_dir = level\n    _workspace_with_layouts(got, run_dir, got["brief"])\n    _save(got, revision=1, choices={"time_of_day": "midnight"})\n    calls = []\n    out = walking.walk(got["path"], EventSink(run_dir, "r", "w"), run_dir, leg=_fake(calls))\n    assert calls[0][2:4] == ["batch", "create"] and [a[2] for a in calls[1:]] == ["approve", "approve", "run", "walk"]\n    imported = json.loads((Path(calls[0][4]).parent / "briefs" / "late_shift_001.json").read_text(encoding="utf-8"))\n    assert imported["time_of_day"] == "midnight"\n    assert out["design_revision"] == 2 and "revision 2" in out["label"]\n\n\ndef test_a_layout_change_makes_the_walk_ask_for_new_layouts(level):\n    got, run_dir = level\n    _workspace_with_layouts(got, run_dir, got["brief"])\n    _save(got, revision=1, choices={"road_grammar": "cross"})\n    calls = []\n    with pytest.raises(layouts.LayoutError) as e:\n        walking.walk(got["path"], EventSink(run_dir, "r", "w"), run_dir, leg=_fake(calls))\n    assert e.value.code == "needs_new_layouts" and "Streets" in str(e.value) and calls == []\n', 'apps/godot/tests/test_level_edit.gd': 'extends SceneTree\n## The Level tab\'s form, headless: every control\'s value is editable in the form and read back exactly as the\n## factory takes it -- a choice by its value, not its label; a whole number; yes/no; words -- and a changed choice\n## reads back changed. After a save, the panel says what comes next from what the change rebuilds.\n##\n##     godot --headless --path <this project> --script res://tests/test_level_edit.gd\n##\n## Prints PASS or FAIL lines; quits 0 only when every case passed. Saving against the real factory is proven by the\n## factory\'s `patches/lf_revise/` records.\n\nconst LevelPanel := preload("res://addons/gabagool_factory/level_panel.gd")\n\nvar _failures := 0\nconst CONTROLS := [\n\t{"key": "name", "label": "Level name", "type": "text", "support": "supported"},\n\t{"key": "time_of_day", "label": "Time of day", "type": "choice", "support": "supported",\n\t\t"options": [{"value": "morning", "label": "Morning"}, {"value": "evening", "label": "Evening"},\n\t\t\t{"value": "midnight", "label": "Midnight"}]},\n\t{"key": "candidate_count", "label": "Layouts to generate", "type": "integer", "min": 1, "max": 8,\n\t\t"support": "supported"},\n\t{"key": "roof_props", "label": "Roof clutter", "type": "boolean", "support": "supported"},\n\t{"key": "objective_hypotheses", "label": "Objective steps", "type": "list", "support": "intent"},\n\t{"key": "notes", "label": "Notes", "type": "longtext", "support": "intent"},\n]\n\n\nfunc _initialize() -> void:\n\t_run.call_deferred()\n\n\nfunc _check(ok: bool, what: String) -> void:\n\tprint(("PASS " if ok else "FAIL ") + what)\n\tif not ok:\n\t\t_failures += 1\n\n\nfunc _run() -> void:\n\tvar panel: Control = LevelPanel.new()\n\troot.add_child(panel)\n\tawait process_frame\n\tpanel.design = {"name": "Late Shift", "revision": 3, "template": "restaurant_row",\n\t\t"choices": {"time_of_day": "evening", "candidate_count": 3, "roof_props": true},\n\t\t"intent": {"objective_hypotheses": ["reach_office", "crack_safe"], "notes": "after closing"}}\n\tpanel._on_controls({"controls": CONTROLS})\n\tvar values: Dictionary = panel.form_values()\n\t_check(values["name"] == "Late Shift", "the name reads back")\n\t_check(values["choices"] == {"time_of_day": "evening", "candidate_count": 3, "roof_props": true},\n\t\t"choices read back by value: %s" % [values["choices"]])\n\t_check(values["intent"] == {"objective_hypotheses": ["reach_office", "crack_safe"], "notes": "after closing"},\n\t\t"intent reads back as the factory takes it: %s" % [values["intent"]])\n\n\tvar rows: Array = panel._form.get_root().get_children()\n\trows[1].set_range(1, 2)            # Time of day -> Midnight\n\trows[2].set_range(1, 5)            # five layouts\n\trows[3].set_checked(1, false)      # no roof clutter\n\tvalues = panel.form_values()\n\t_check(values["choices"] == {"time_of_day": "midnight", "candidate_count": 5, "roof_props": false},\n\t\t"changed values read back changed: %s" % [values["choices"]])\n\n\tvar saved: Dictionary = panel.design.duplicate(true)\n\tsaved["revision"] = 4\n\tpanel._on_saved({"design": saved, "path": "", "rebuilds": ["lighting"]}, {"revision": 3})\n\t_check(panel._walk_status.text.contains("Walk the level to see it (rebuilds the lighting)"),\n\t\t"a lighting change says to walk: %s" % panel._walk_status.text)\n\t_check(not panel._undo.disabled, "and Undo is offered")\n\tsaved = saved.duplicate(true)\n\tsaved["revision"] = 5\n\tpanel._on_saved({"design": saved, "path": "", "rebuilds": ["layout"]}, {})\n\t_check(panel._walk_status.text.contains("generate layouts again"), "a layout change says to generate again")\n\t_check(panel._undo.disabled, "and an undone save offers no second undo")\n\n\tpanel.queue_free()\n\tprint("DONE failures=%d" % _failures)\n\tquit(1 if _failures else 0)\n', 'apps/godot/tests/test_level_edit.gd.uid': 'uid://d4m6eggcyj172\n'}
CHANGELOG = '## [0.248.0] - change a level\'s settings and see the change in the next walk\n\n**Increment 6 of the no-AI authoring loop** (the factory\'s `docs/AUTHORING_LOOP.md`; roadmap 316).\n\n### Added\n- **`update_design`** (`design.update_design`, `design.rebuilds_between`). A change is the design\'s next revision,\n  never an overwrite.\n  - The caller names the revision it edited; a design saved since is a `conflict`.\n  - Every value is checked against the template\'s catalog; a save that changes nothing is refused.\n  - The answer says what the change rebuilds (layout, lighting, backdrop, art), so the panel can say what comes\n    next.\n- **The walk builds the current revision**. `walking.walk` re-writes the design\'s request and re-imports it\n  (`batch create`) before the art leg; `layouts.write_request` is the one writer, shared with generation. It refuses\n  with `needs_new_layouts`, naming the control, when a change that rebuilds the layout (streets, layouts to\n  generate) came after the layouts were generated (`layouts.latest_layout_record`).\n- **An editable form** on the Level tab:\n  - choices as drop-downs of their options, a whole number as a spin range, yes/no as a check box, words and text\n    as text;\n  - Save changes makes the next revision and says whether to walk or to generate again;\n  - Undo last save saves the previous values as a new revision; history is never rewritten.\n\n### Measured\n- On the trial design: time of day evening -> midnight saved as revision 2 (`rebuilds: lighting`), then walked\n  through the worker in 7 min 20 s. The walk is named "Panel Trial, revision 2, layout seed 9205" and its\n  self-check passed.\n  - Re-ran: `lux_apply`, `lot_assemble` (all three layouts), `themed_site_assemble`, `presentation_compose`.\n  - Cache hits: the shells, the kit, dressing, walk tests and Laser Tag.\n- "Lighting" understates it: Lot\'s site lights follow the time of day, so the site re-assembles too. It does so\n  for every layout, not only the chosen one.\n\n### Changed\n- `tests/service/test_walking.py` expects the walk to start with the re-import.\n- `apps/godot/tests/test_level_panel.gd` reads a choice from its drop-down: the chosen option\'s label.\n\n### Tests\n- `tests/service/test_revise.py` (fails on 0.247.0):\n  - the next revision and what it rebuilds (time -> lighting, streets -> layout, notes -> nothing);\n  - a stale revision, an unchanged save and a bad value refused;\n  - the walk importing the current revision\'s brief and naming revision 2;\n  - a layout change asking for new layouts before anything runs.\n- `apps/godot/tests/test_level_edit.gd`: every kind of control read back as the factory takes it, a change read\n  back changed, and the panel\'s next step after a lighting and a layout change.\n\n'
OLD_VERSION, NEW_VERSION = '0.247.0', '0.248.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (LF / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: level_factory/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: level_factory/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: level_factory/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (LF / name).exists():
            raise SystemExit("REFUSED: level_factory/%s exists already; nothing written" % name)
    v = LF / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = LF / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (LF / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        # 0.243.0 adds whole folders (apps/godot/): a new file's folder is made, never assumed
        (LF / name).parent.mkdir(parents=True, exist_ok=True)
        (LF / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Level Factory %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in level_factory/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
